from pathlib import Path
import json,geopandas as g,numpy as np,shapely
from shapely.ops import polygonize
out=Path('outputs/user_data_test');out.mkdir(exist_ok=True)
city=g.read_file('data/raw/shanghai_boundary.geojson').to_crs(32651).geometry.union_all();bounds=city.bounds
road=g.read_file('data/raw/osm/gis_osm_roads_free_1.shp').to_crs(32651);road=road[road.fclass.isin(['motorway','trunk','primary','secondary','tertiary','residential','unclassified','service','living_street'])&(road.bridge!='T')&(road.tunnel!='T')&(road.layer.fillna(0)==0)].cx[bounds[0]:bounds[2],bounds[1]:bounds[3]]
rail=g.read_file('data/raw/osm/gis_osm_railways_free_1.shp').to_crs(32651);rail=rail[rail.fclass.isin(['rail','light_rail','tram'])&(rail.bridge!='T')&(rail.tunnel!='T')&(rail.layer.fillna(0)==0)].cx[bounds[0]:bounds[2],bounds[1]:bounds[3]]
water=g.read_file('data/raw/osm/gis_osm_water_a_free_1.shp').to_crs(32651);water=water[water.fclass.isin(['water','riverbank','reservoir','dock'])].cx[bounds[0]:bounds[2],bounds[1]:bounds[3]];watergeom=shapely.make_valid(water.geometry.union_all());closures=g.read_file('outputs/road_network_v2/inferred_gap_connectors.gpkg').to_crs(32651);added=g.read_file('data/user_shanghai/national_roads_candidate_filtered.gpkg').to_crs(32651)
print('noding',len(road),'existing',len(added),'candidate additions',flush=True);network=shapely.union_all(np.concatenate([road.geometry.to_numpy(),added.geometry.to_numpy(),closures.geometry.to_numpy(),rail.geometry.to_numpy(),np.array([watergeom.boundary,city.boundary],dtype=object)]));print('polygonizing',flush=True);shapely.prepare(city);faces=[p for p in polygonize(network) if p.area>.05 and city.covers(p.representative_point())];shapely.prepare(watergeom);blocks=g.GeoDataFrame({'id':np.arange(len(faces),dtype='int32')},geometry=faces,crs=32651);blocks['is_water']=[watergeom.covers(p.representative_point()) for p in faces];large=(~blocks.is_water)&(blocks.area>2e6);u=blocks.geometry.union_all();m={'candidate_2025_road_lines':len(added),'candidate_road_km':float(added.length.sum()/1000),'faces':len(blocks),'large_land_faces':int(large.sum()),'large_land_area_km2':float(blocks.area[large].sum()/1e6),'prior_large_land_area_km2':5392.609035587602,'change_km2':float(blocks.area[large].sum()/1e6-5392.609035587602),'gap_m2':float(city.difference(u).area),'overlap_m2':float(blocks.area.sum()-u.area),'invalid':int((~blocks.is_valid).sum())};(out/'candidate_network_metrics.json').write_text(json.dumps(m,indent=2));print(json.dumps(m,indent=2),flush=True);blocks.to_file(out/'candidate_blocks.gpkg',driver='GPKG')
